import boto3

def stream_platform_generation(payload, config=None):
    config = config or {}
    client = boto3.client("bedrock-runtime", region_name=config.get("region", "us-east-1"))

    # Using invoke_model_with_response_stream for streaming capabilities
    # This requires a different model invocation payload structure than 'converse'
    # For simplicity, we'll adapt the payload to a common text generation model like Anthropic Claude.

    # Example with Anthropic Claude on Bedrock
    model_id = config.get("model_id", "anthropic.claude-3-sonnet-20240229-v1:0") # Using Claude 3 Sonnet for streaming

    body = {
        "anthropic_version": "bedrock-2023-05-31",
        "messages": [
            {
                "role": "user",
                "content": payload["text"],
            }
        ],
        "max_tokens": 100,
        "temperature": 0.5,
    }

    response = client.invoke_model_with_response_stream(
        modelId=model_id,
        contentType="application/json",
        accept="application/json",
        body=body
    )

    for event in response['body']:
        chunk = event.get('chunk')
        if chunk:
            # Decode the bytes and then parse the JSON string
            parsed_chunk = chunk['bytes'].decode('utf-8')
            # In a real scenario, you'd parse 'parsed_chunk' as JSON
            # For this example, we'll just yield the raw chunk bytes to demonstrate streaming
            yield {"raw_chunk_bytes": parsed_chunk}

import boto3

def collect_platform_metadata(payload, config=None):
    config = config or {}
    client = boto3.client("bedrock-runtime", region_name=config.get("region", "us-east-1"))
    model_id = config.get("model_id", "us.amazon.nova-pro-v1:0")

    response = client.converse(
        modelId=model_id,
        messages=[{"role": "user", "content": [{"text": payload["text"]}]}],
    )

    text = "".join(block["text"] for block in response["output"]["message"]["content"] if "text" in block)

    metadata = {
        "invocation_metrics": response.get("amazon-bedrock-invocation-metrics"),
        "usage": response.get("usage"), # Contains input/output token counts
        "model_id": model_id,
        "response_id": response["output"]["responseId"]
    }

    return {"text": text, "metadata": metadata}

import boto3

def get_bedrock_client(service_name: str = "bedrock-runtime", region_name: str = "us-east-1"):
    """Provides a configured boto3 client for AWS Bedrock."""
    return boto3.client(service_name, region_name=region_name)


def get_bedrock_model_id(model_alias: str = "nova"):
    """Resolves a model alias to a concrete Bedrock model ID."""
    # This is a simplified mapping. In a real application, this could be
    # loaded from configuration, a database, or dynamically discovered.
    model_map = {
        "nova": "us.amazon.nova-pro-v1:0",
        "claude-sonnet": "anthropic.claude-3-sonnet-20240229-v1:0",
        "titan-text-express": "amazon.titan-text-express-v1"
    }
    return model_map.get(model_alias, model_alias)

from typing import TypedDict, Optional, List, Dict, Any

class PlatformInput(TypedDict):
